# Generated by curate-skills
# Workflow: corvallis_weather_precip_gapfill
# Function: plot_gapfill_comparison

import os
import tempfile

import matplotlib

matplotlib.use("Agg")
import matplotlib.dates as mdates  # noqa: E402
import matplotlib.pyplot as plt  # noqa: E402
import pandas as pd  # noqa: E402


def plot_gapfill_comparison(folder: str, input1: str, output1: str) -> None:
    tmpdir = tempfile.mkdtemp()
    local_in = os.path.join(tmpdir, "precip_gapfilled.csv")
    local_out = os.path.join(tmpdir, "corvallis_precip_gapfill_2015_2025.png")

    faasr_get_file(local_file=local_in, remote_folder=folder, remote_file=input1)

    df = pd.read_csv(local_in)
    required = {"date", "prcp_raw_mm", "prcp_filled_mm", "filled"}
    missing_cols = required - set(df.columns)
    if missing_cols:
        msg = f"plot_gapfill_comparison: input {input1} missing columns {sorted(missing_cols)}"
        faasr_log(msg)
        raise ValueError(msg)

    df["date"] = pd.to_datetime(df["date"], errors="coerce")
    df = df.dropna(subset=["date"]).sort_values("date")
    df["prcp_raw_mm"] = pd.to_numeric(df["prcp_raw_mm"], errors="coerce")
    df["prcp_filled_mm"] = pd.to_numeric(df["prcp_filled_mm"], errors="coerce")
    df["filled"] = pd.to_numeric(df["filled"], errors="coerce").fillna(0).astype(int)

    start = pd.Timestamp("2015-01-01")
    end = pd.Timestamp("2025-12-31")
    sub = df[(df["date"] >= start) & (df["date"] <= end)].copy()
    if sub.empty:
        msg = "plot_gapfill_comparison: no records between 2015-01-01 and 2025-12-31"
        faasr_log(msg)
        raise ValueError(msg)

    # Reindex to a complete daily calendar so missing days in the raw series are NaN gaps.
    plot_end = min(end, sub["date"].max())
    full_idx = pd.date_range(start, plot_end, freq="D")
    sub = sub.set_index("date").reindex(full_idx)
    sub.index.name = "date"

    raw = sub["prcp_raw_mm"]
    filled_series = sub["prcp_filled_mm"]
    is_filled = sub["filled"].fillna(0).astype(int) == 1
    n_filled = int(is_filled.sum())
    n_days = len(sub)

    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(14, 8), sharex=True)

    # Top: raw daily precipitation; NaN days break the line, so missing days appear as gaps.
    ax1.plot(raw.index, raw.values, color="tab:blue", linewidth=0.6,
             marker=".", markersize=1.5, label="observed (raw)")
    ax1.set_title("Raw daily precipitation (missing days shown as gaps)")
    ax1.set_ylabel("Precipitation (mm)")
    ax1.grid(alpha=0.3)

    # Bottom: gap-filled series, observed vs filled days in contrasting colours.
    obs_mask = ~is_filled & filled_series.notna()
    fill_mask = is_filled & filled_series.notna()
    ax2.vlines(sub.index[obs_mask], 0, filled_series[obs_mask].values,
               color="tab:blue", linewidth=0.7, label="observed")
    ax2.vlines(sub.index[fill_mask], 0, filled_series[fill_mask].values,
               color="tab:orange", linewidth=0.9, label="gap-filled")
    ax2.scatter(sub.index[fill_mask], filled_series[fill_mask].values,
                color="tab:orange", s=4, zorder=3)
    ax2.set_title("Gap-filled daily precipitation")
    ax2.set_ylabel("Precipitation (mm)")
    ax2.set_xlabel("Date")
    ax2.legend(loc="upper right")
    ax2.grid(alpha=0.3)

    ax2.xaxis.set_major_locator(mdates.YearLocator())
    ax2.xaxis.set_major_formatter(mdates.DateFormatter("%Y"))
    ax2.set_xlim(full_idx[0], full_idx[-1])

    period = f"{full_idx[0]:%Y-%m-%d} to {full_idx[-1]:%Y-%m-%d}"
    fig.suptitle(
        "Corvallis, Oregon (station USC00351862) daily precipitation, raw vs gap-filled, "
        f"{period}\n{n_filled} of {n_days} days in the plotted period were gap-filled",
        fontsize=12,
    )
    fig.tight_layout(rect=(0, 0, 1, 0.94))
    fig.savefig(local_out, dpi=150, format="png")
    plt.close(fig)

    faasr_put_file(local_file=local_out, remote_folder=folder, remote_file=output1)
    faasr_log(
        f"plot_gapfill_comparison: plotted {period} ({n_days} days, {n_filled} filled) "
        f"to {output1}"
    )
